import SwiftUI
struct MixesView: View {
 @StateObject private var model:MixCatalogViewModel;@State private var filters=false;@State private var results=false;let makeMixDetailModel:(MixPreview)->MixDetailViewModel
 private let columns=[GridItem(.flexible(),spacing:10),GridItem(.flexible(),spacing:10)]
 init(model:@autoclosure @escaping()->MixCatalogViewModel,makeMixDetailModel:@escaping(MixPreview)->MixDetailViewModel){_model=StateObject(wrappedValue:model());self.makeMixDetailModel=makeMixDetailModel}
 var body:some View{NavigationStack{ScrollView{LazyVGrid(columns:columns,spacing:10){ForEach(model.visibleMixes){mix in NavigationLink(value:mix){MixCardView(mix:mix)}.buttonStyle(.plain).accessibilityIdentifier("mix.card.\(mix.id.uuidString)")}}.padding(.horizontal,16).padding(.bottom,24)}.background(AppTheme.background).overlay{if model.isLoading&&model.catalog.isEmpty{ProgressView()}}.refreshable{await model.refresh()}.task{await model.appear()}.navigationTitle(L10n.Tab.mixes).searchable(text:$model.search,prompt:L10n.Mix.search).toolbar{Button{filters=true}label:{Image(systemName:"slider.horizontal.3")}.accessibilityLabel(Text(L10n.Filters.title)).accessibilityIdentifier("mix.filters")}.sheet(isPresented:$filters){MixFilterView(model:MixFilterViewModel(catalog:model.catalog,filter:model.filter)){model.apply($0);results=true}}.navigationDestination(isPresented:$results){MixResultsView(model:model)}.navigationDestination(for:MixPreview.self){MixDetailView(model:makeMixDetailModel($0))}}}
}
private struct MixResultsView:View{@ObservedObject var model:MixCatalogViewModel;@State private var filters=false;let columns=[GridItem(.flexible()),GridItem(.flexible())];var body:some View{ScrollView{if model.ideal.isEmpty&&model.possible.isEmpty{ContentUnavailableView(L10n.Filters.Empty.title,systemImage:"slider.horizontal.3",description:Text(L10n.Filters.Empty.message)).padding(.top,80)}else{LazyVStack(alignment:.leading,spacing:24){section(L10n.Results.ideal,model.ideal);section(L10n.Results.possible,model.possible)}.padding()}}.navigationTitle(L10n.Results.title).accessibilityIdentifier("screen.mixResults").toolbar{Button(L10n.Results.edit){filters=true}}.sheet(isPresented:$filters){MixFilterView(model:MixFilterViewModel(catalog:model.catalog,filter:model.filter),onApply:model.apply)}};@ViewBuilder func section(_ title:String,_ mixes:[MixPreview])->some View{if !mixes.isEmpty{VStack(alignment:.leading){Text(title).font(.title2.bold());LazyVGrid(columns:columns){ForEach(mixes){mix in NavigationLink(value:mix){MixCardView(mix:mix)}.buttonStyle(.plain)}}}}}}
